//! Odin: `azul/azul.odin` (generated by `doc/src/codegen/v2/lang_odin`,
//! `import azul "azul"`).
//!
//! Spellings are the C ones inside package `azul`: foreign procs
//! `azul.AzCssProperty_textColor(..)`, variant constructors
//! `azul.AzLayoutWidth_px(..)`, enums `azul.AzLayoutDisplay.Flex`, structs
//! compound literals with named fields (`azul.AzColorU{r = 255, ..}`, Odin
//! keywords get `_`), a tagged union a `#raw_union` of `{tag, payload}`
//! variant structs (`azul.AzLayoutWidthValue{Exact = {tag = 6, payload = ..}}`).
//! A Vec is copied from a slice literal (`&[]azul.AzX{..}[0]`), a string
//! goes through the `css_str` helper (`AzString_fromUtf8`, as in
//! `examples/odin`). Indentation is tabs (`odin fmt`).

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, module_any, unicode_u4, variant_ctor_method,
        ExprSyntax,
    },
    lower_types::union_tag,
    CodegenBackend, GeneratedFile,
};

/// The Odin printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Odin;

/// `is_odin_keyword` of `lang_odin/mod.rs`.
const KEYWORDS: &[&str] = &[
    "asm", "auto_cast", "bit_set", "break", "case", "cast", "context", "continue", "defer",
    "distinct", "do", "dynamic", "else", "enum", "fallthrough", "for", "foreign", "if", "import",
    "in", "map", "matrix", "not_in", "or_else", "or_return", "package", "proc", "return",
    "struct", "switch", "transmute", "typeid", "union", "using", "when", "where",
];

fn ident(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

/// `T{a = 1, b = 2}`, one field per line when `broken`.
fn literal(ty: Doc, fields: Vec<Doc>, broken: bool) -> Doc {
    Doc::cat(vec![ty, Doc::list("{", fields, ", ", "}", false, broken, true)])
}

impl ExprSyntax for Odin {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let (bits, int) = if ty == Prim::F64 {
            ("f64", "u64")
        } else {
            ("f32", "u32")
        };
        let pattern = match (text, ty == Prim::F64) {
            ("nan", false) => "0x7fc00000",
            ("inf", false) => "0x7f800000",
            ("-inf", false) => "0xff800000",
            ("nan", true) => "0x7ff8000000000000",
            ("inf", true) => "0x7ff0000000000000",
            ("-inf", true) => "0xfff0000000000000",
            _ => return text.to_string(),
        };
        format!("transmute({bits}){int}({pattern})")
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("css_str(\"{}\")", escape_quoted(s, &[], &unicode_u4)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("azul.Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("azul.Az{ty}.{}", ident(variant))),
            EnumShape::Tagged => Doc::call(
                format!("azul.Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let mut inner = vec![Doc::text(format!("tag = {tag}"))];
                if let Some(p) = args.into_iter().next() {
                    inner.push(Doc::cat(vec![Doc::text("payload = "), p]));
                }
                literal(
                    Doc::text(format!("azul.Az{ty}")),
                    vec![Doc::cat(vec![
                        Doc::text(format!("{variant} = ")),
                        Doc::list("{", inner, ", ", "}", false, broken, true),
                    ])],
                    broken,
                )
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{} = ", ident(&k))), v]))
            .collect();
        literal(Doc::text(format!("azul.Az{ty}")), fields, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("azul.Az{ty}_create()"));
        }
        let n = items.len();
        Doc::cat(vec![
            Doc::text(format!("azul.Az{ty}_copyFromPtr(&[]azul.Az{elem}")),
            Doc::list("{", items, ", ", "}", false, broken, true),
            Doc::text(format!("[0], {n})")),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!(
            "#panic(\"not expressible: {}\")",
            escape_quoted(what, &[], &unicode_u4)
        ))
    }
}

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&Odin, item) {
        out.push_str(&format!("// {line}\n"));
    }
    let name = item.name.snake();
    match item_doc(&Odin, item) {
        Ok(doc) => {
            out.push_str(&format!(
                "{name} :: proc() -> azul.Az{} {{\n\treturn {}\n}}\n",
                item.ty,
                render(&doc, "\t", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                "// {name}: not expressible with the Odin bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

const CSS_STR: &str = "css_str :: proc(s: string) -> azul.AzString {
\treturn azul.AzString_fromUtf8(raw_data(s), uint(len(s)))
}
";

impl CodegenBackend for Odin {
    fn lang(&self) -> &'static str {
        "odin"
    }

    fn display_name(&self) -> &'static str {
        "Odin"
    }

    fn extension(&self) -> &'static str {
        "odin"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "// Generated by azul-css codegen (Odin). Do not edit by hand.\npackage main\n\nimport \
             azul \"azul\"\n",
        );
        if module_any(m, &|e| matches!(e, Expr::Str(_))) {
            out.push('\n');
            out.push_str(CSS_STR);
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "// Copy target/codegen/azul.odin to ./azul/ and libazul here, then:\n//   odin run . \
             -extra-linker-flags:\"-L.\"\npackage main\n\nimport \"core:fmt\"\n\nmain :: proc() \
             {\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = item.name.snake();
            main.push_str(&format!(
                "\t{name}_value := {name}()\n\tfmt.println(\"{name}:\", {name}_value.len, \
                 \"properties\")\n"
            ));
        }
        main.push_str("}\n");
        vec![
            GeneratedFile {
                path: "styles.odin".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.odin".to_string(),
                contents: main,
            },
        ]
    }
}
